func mnemonico(op) {
    if (op == 0) {
        return "ADD";
    }
    if (op == 1) {
        return "SUB";
    }
    return "MUL";
}

func folha(e, n) {
    if (n == 0) {
        return "?";
    }
    return substr(e, 0, n);
}

var e = input();
print("    " + mnemonico(1) + "    r2");
