class Tokens {
    var tipos = [];
    var valores = [];
    func adicionar(tipo, valor) {
        this.tipos.append(tipo);
        this.valores.append(valor);
    }
}

var e = input();
var tk = new Tokens();
var i = 0;
while (i < len(e)) {
    var c = substr(e, i, 1);
    if (c >= "0" && c <= "9") {
        var num = "";
        while (i < len(e) && substr(e, i, 1) >= "0" && substr(e, i, 1) <= "9") {
            num = num + substr(e, i, 1);
            i = i + 1;
        }
        tk.adicionar(0, to_number(num));
    } else {
        if (c != " ") {
            tk.adicionar(1, i);
        }
        i = i + 1;
    }
}

var j = 0;
var linha = "";
while (j < len(tk.tipos)) {
    if (j > 0) {
        linha = linha + " ";
    }
    if (tk.tipos[j] == 0) {
        linha = linha + "NUM(" + to_string(tk.valores[j]) + ")";
    } else {
        linha = linha + "SIM(" + substr(e, tk.valores[j], 1) + ")";
    }
    j = j + 1;
}
print(linha);
print("total=" + to_string(len(tk.tipos)));

func montar(n) {
    var v = []; for (var i in range(n)) { v.append(i); } return v;
}
var v = montar(3); v[0] = 7; print(v.pop(), v[0], len(v));
var vazio = []; print(len(vazio) - 1);

func fat(n) {
    if (n <= 1) { return 1; } return n * fat(n - 1);
}
print(fat(6));

class Estado {
    var v = []; var total = 0;
    func add(n) { this.v.append(n); }
    func soma(i) {
        if (i >= len(this.v)) { return 0.0; }
        this.total = this.total + this.v[i]; return this.v[i] + this.soma(i + 1);
    }
    func texto(i) {
        if (i >= len(this.v)) { return "fim"; }
        return to_string(this.v[i]) + ":" + this.texto(i + 1);
    }
}
func preencher(obj, n) {
    if (n <= 0) { return; } obj.add(n); preencher(obj, n - 1);
}
var obj = new Estado(); preencher(obj, 3);
print(obj.soma(0), obj.total, obj.texto(0));
